votes.sql:
WITH complaint_counts AS (
    SELECT staff_id, COUNT(*) AS cnt
    FROM Complaints
    GROUP BY staff_id
), max_count AS (
    SELECT MAX(cnt) AS max_cnt FROM complaint_counts
)
SELECT staff_id
FROM complaint_counts
WHERE cnt = (SELECT max_cnt FROM max_count);

